"""Generate docs/rules.md from the live rule registry so documentation never drifts from code."""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))

from skillchain.capabilities.manifest import MANIFEST_RULE_IDS
from skillchain.rules import default_registry
from skillchain.sandbox.detonate import DYN_RULES


def main() -> None:
    out: list[str] = [
        "# Rule catalogue",
        "",
        "Generated by `make docs-rules`. Every rule carries a *confidence*:",
        "",
        "- **deterministic**: a reproducible fact about the artefact (e.g. a zero-width character exists).",
        "- **heuristic**: a pattern-based suspicion about intent (e.g. text that reads like an instruction override).",
        "",
        "Policies treat them differently: by default only deterministic findings can *block*.",
        "",
        "| ID | Title | Severity | Confidence | Category |",
        "|---|---|---|---|---|",
    ]
    rows = [
        (
            d.id,
            d.title,
            d.severity.value,
            d.confidence.value,
            d.category.value,
            d.description,
            d.remediation,
            d.references,
        )
        for d in default_registry().descriptors()
    ]
    rows += [
        (
            rid,
            t,
            s.value,
            "deterministic",
            "manifest",
            t,
            "Declare the capability or remove the behaviour.",
            (),
        )
        for rid, t, s in MANIFEST_RULE_IDS
    ]
    rows += [
        (rid, t, s.value, "deterministic", "sandbox", t, "Behaviour observed at runtime in the sandbox.", ())
        for rid, (t, s) in DYN_RULES.items()
    ]
    rows.sort()
    for rid, title, sev, conf, cat, *_ in rows:
        out.append(f"| [`{rid}`](#{rid.lower()}) | {title} | {sev} | {conf} | {cat} |")
    out.append("")
    out.append("## Details")
    out.append("")
    for rid, title, sev, conf, cat, desc, rem, refs in rows:
        out += [
            f"### {rid}",
            "",
            f"**{title}** — severity `{sev}`, confidence `{conf}`, category `{cat}`",
            "",
            desc or title,
            "",
        ]
        if rem:
            out += [f"*Remediation:* {rem}", ""]
        for r in refs:
            out.append(f"- {r}")
        if refs:
            out.append("")
    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
